package com.campusconnect.enrollment;
import com.campusconnect.course.*; import com.campusconnect.user.*; import org.springframework.http.HttpStatus; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.security.Principal; import java.util.*;
@RestController @RequestMapping("/api/enrollments") public class EnrollmentController { private final EnrollmentRepository enrollments; private final CourseRepository courses; private final UserRepository users; public EnrollmentController(EnrollmentRepository e,CourseRepository c,UserRepository u){enrollments=e;courses=c;users=u;}
@GetMapping public List<Map<String,Object>> mine(Principal p){return enrollments.findByStudentEmailOrderByEnrolledAtDesc(p.getName()).stream().map(e->Map.<String,Object>of("id",e.getId(),"courseId",e.getCourse().getId(),"courseTitle",e.getCourse().getTitle(),"courseCode",e.getCourse().getCode(),"enrolledAt",e.getEnrolledAt())).toList();}
@PostMapping("/{courseId}") @ResponseStatus(HttpStatus.CREATED) public Map<String,Object> enroll(@PathVariable Long courseId,Principal p){var course=courses.findById(courseId).orElseThrow(()->new IllegalArgumentException("Course not found"));var user=users.findByEmailIgnoreCase(p.getName()).orElseThrow(()->new IllegalArgumentException("User not found"));if(user.getRole()!=Role.STUDENT)throw new IllegalArgumentException("Only students can enroll");if(enrollments.findByCourseIdAndStudentEmail(courseId,p.getName()).isPresent())throw new IllegalArgumentException("Already enrolled");var e=enrollments.save(new Enrollment(course,user));return Map.of("id",e.getId(),"courseId",courseId,"courseTitle",course.getTitle());}
@DeleteMapping("/{courseId}") @ResponseStatus(HttpStatus.NO_CONTENT) public void unenroll(@PathVariable Long courseId,Principal p){var e=enrollments.findByCourseIdAndStudentEmail(courseId,p.getName()).orElseThrow(()->new IllegalArgumentException("Enrollment not found"));enrollments.delete(e);}
@GetMapping("/course/{courseId}") @PreAuthorize("hasAnyRole('FACULTY','ADMIN')") public List<Map<String,Object>> roster(@PathVariable Long courseId){return enrollments.findByCourseId(courseId).stream().map(e->Map.<String,Object>of("studentId",e.getStudent().getId(),"name",e.getStudent().getName(),"email",e.getStudent().getEmail())).toList();}}
